// LAB: Make subregister width an explicit input
// Model writes of 16, 32, or 64 bits to a 64-bit x86 register. A 32-bit write clears the high half; a 16-bit write preserves the other bits. Reject unsupported widths.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <cstdint>
#include <iostream>

int main() {
    const std::uint64_t old = 0xFFFFFFFF00000000ULL;
    const std::uint32_t eax = 7;
    const std::uint64_t after_eax = eax;
    const std::uint64_t after_ax = (old & ~0xFFFFULL) | 7ULL;
    std::cout << std::hex << after_eax << ' ' << after_ax << '\n';
    assert(after_eax == 7 && after_ax == 0xFFFFFFFF00000007ULL);
}

#include <cassert>
#include <cstdint>
#include <iostream>
#include <stdexcept>

std::uint64_t write_register(std::uint64_t old, std::uint64_t value, unsigned width) {
    if(width == 64) return value;
    if(width == 32) return static_cast<std::uint32_t>(value);
    if(width == 16) return (old & ~std::uint64_t{0xFFFF}) | (value & 0xFFFFu);
    throw std::invalid_argument("unsupported width");
}

int main() {
    const std::uint64_t old = 0xFFFFFFFF00000000ULL;
    assert(write_register(old,7,32) == 7);
    assert(write_register(old,7,16) == 0xFFFFFFFF00000007ULL);
    assert(write_register(old,9,64) == 9);
    bool rejected = false;
    try { write_register(old,7,8); } catch(const std::invalid_argument&) { rejected = true; }
    assert(rejected);
    std::cout << std::hex << write_register(old,7,32) << ' ' << write_register(old,7,16) << '\n';
}
